import math

def _render(z):
    cx, cy, a, b, th, amp = z
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            q = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if q == 0.0:
                sd = min(a, b)
            else:
                grad = math.sqrt((u / (a * a)) ** 2 + (v / (b * b)) ** 2)
                sd = (1.0 - q) * q / grad
            t = sd + 0.5
            if t < 0.0:
                t = 0.0
            elif t > 1.0:
                t = 1.0
            out.append(amp * t)
    return out

def encode(img):
    # Thresholded moments give a reliable initial center and orientation.
    sw = sx = sy = 0.0
    for i in range(16):
        for j in range(16):
            w = max(0.0, img[i * 16 + j] - 0.18)
            sw += w
            sx += w * j
            sy += w * i
    if sw <= 1e-8:
        z = [7.5, 7.5, 3.0, 2.5, 0.0, 0.8]
    else:
        cx, cy = sx / sw, sy / sw
        xx = xy = yy = 0.0
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[i * 16 + j] - 0.18)
                dx, dy = j - cx, i - cy
                xx += w * dx * dx
                xy += w * dx * dy
                yy += w * dy * dy
        xx, xy, yy = xx / sw, xy / sw, yy / sw
        angle = 0.5 * math.atan2(2.0 * xy, xx - yy)
        disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
        l1 = max(0.0, (xx + yy + disc) * 0.5)
        l2 = max(0.0, (xx + yy - disc) * 0.5)
        a = min(4.8, max(1.4, 2.0 * math.sqrt(l1)))
        b = min(4.8, max(1.4, 2.0 * math.sqrt(l2)))
        if b > a:
            a, b = b, a
            angle += math.pi * 0.5
        peak = max(img)
        z = [cx, cy, a, b, angle, min(1.0, max(0.6, peak))]

    def loss(params):
        pred = _render(params)
        return sum((x - y) ** 2 for x, y in zip(img, pred))

    steps = [0.5, 0.5, 0.45, 0.45, 0.18, 0.08]
    best = loss(z)
    for _ in range(70):
        changed = False
        for k in range(6):
            for direction in (-1.0, 1.0):
                cand = z[:]
                cand[k] += direction * steps[k]
                if k < 2:
                    cand[k] = min(15.0, max(0.0, cand[k]))
                elif k in (2, 3):
                    cand[k] = min(4.8, max(1.2, cand[k]))
                elif k == 5:
                    cand[k] = min(1.1, max(0.4, cand[k]))
                value = loss(cand)
                if value < best:
                    z, best = cand, value
                    changed = True
        if not changed:
            steps = [s * 0.6 for s in steps]
            if max(steps) < 0.008:
                break
    return z

def decode(z):
    return _render(z)
