import math

def _render(z):
    cx, cy, a, b, th, amp = z
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if rho < 1e-9:
                signed = min(a, b)
            else:
                radius = math.sqrt((u*u + v*v) / (rho*rho))
                signed = (1.0 - rho) * radius
            p = max(0.0, min(1.0, signed + 0.5))
            out.append(amp * p)
    return out

def encode(img):
    # Estimate center and covariance from the bright pixels.
    m = sx = sy = 0.0
    weights = []
    for i in range(16):
        for j in range(16):
            w = max(0.0, img[i*16+j] - 0.18)
            weights.append(w)
            m += w
            sx += w*j
            sy += w*i
    if m < 1e-8:
        z = [7.5, 7.5, 2.8, 2.0, 0.0, 0.8]
    else:
        cx, cy = sx/m, sy/m
        xx = yy = xy = 0.0
        for i in range(16):
            for j in range(16):
                w = weights[i*16+j]
                dx, dy = j-cx, i-cy
                xx += w*dx*dx
                yy += w*dy*dy
                xy += w*dx*dy
        xx, yy, xy = xx/m, yy/m, xy/m
        disc = math.sqrt(max(0.0, (xx-yy)**2 + 4*xy*xy))
        l1 = max(0.5, (xx+yy+disc)*0.5)
        l2 = max(0.5, (xx+yy-disc)*0.5)
        a = max(1.4, min(4.6, math.sqrt(4*l1)))
        b = max(1.4, min(4.6, math.sqrt(4*l2)))
        th = 0.5*math.atan2(2*xy, xx-yy)
        if a < b:
            a, b = b, a
            th += math.pi/2
        amp = max(0.6, min(1.0, max(img)))
        z = [cx, cy, a, b, th, amp]

    def loss(q):
        pred = _render(q)
        return sum((img[k]-pred[k])**2 for k in range(256))

    # Coordinate search refines the moment estimate against the actual pixels.
    steps = [0.8, 0.8, 0.7, 0.7, 0.30, 0.12]
    for _ in range(7):
        for d in range(6):
            best, bestloss = z[:], loss(z)
            for sign in (-1.0, 1.0):
                q = z[:]
                q[d] += sign*steps[d]
                if d < 2:
                    q[d] = max(0.0, min(15.0, q[d]))
                elif d in (2, 3):
                    q[d] = max(1.3, min(4.8, q[d]))
                elif d == 4:
                    q[d] = (q[d] + math.pi/2) % math.pi - math.pi/2
                else:
                    q[d] = max(0.55, min(1.05, q[d]))
                val = loss(q)
                if val < bestloss:
                    best, bestloss = q, val
            z = best
        steps = [s*0.55 for s in steps]
    if z[2] < z[3]:
        z[2], z[3] = z[3], z[2]
        z[4] += math.pi/2
    return z

def decode(z):
    return _render(z)
