import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if rho < 1e-12:
                signed = min(a, b)
            else:
                signed = (1.0 - rho) * math.sqrt(u * u + v * v) / rho
            out.append(amp * max(0.0, min(1.0, signed + 0.5)))
    return out

def encode(img):
    def moments(threshold):
        sw = sx = sy = 0.0
        weights = []
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[i * 16 + j] - threshold)
                weights.append(w)
                sw += w
                sx += w * j
                sy += w * i
        if sw < 1e-9:
            return [7.5, 7.5, 3.0, 2.0, 0.0]
        cx, cy = sx / sw, sy / sw
        xx = yy = xy = 0.0
        for i in range(16):
            for j in range(16):
                w = weights[i * 16 + j]
                dx, dy = j - cx, i - cy
                xx += w * dx * dx
                yy += w * dy * dy
                xy += w * dx * dy
        xx, yy, xy = xx / sw, yy / sw, xy / sw
        disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
        a = math.sqrt(max(0.5, 2.0 * (xx + yy + disc) * 0.5))
        b = math.sqrt(max(0.5, 2.0 * (xx + yy - disc) * 0.5))
        th = 0.5 * math.atan2(2.0 * xy, xx - yy)
        if b > a:
            a, b = b, a
            th += math.pi * 0.5
        return [cx, cy, max(1.2, min(4.8, a)),
                max(1.2, min(4.8, b)), th]

    def fit_amp(p):
        base = _render(p[0], p[1], p[2], p[3], p[4], 1.0)
        dot = sum(x * y for x, y in zip(img, base))
        den = sum(x * x for x in base) + 1e-12
        amp = max(0.4, min(1.2, dot / den))
        err = sum((x - amp * y) ** 2 for x, y in zip(img, base))
        return err, amp

    best_p = None
    best_err = float("inf")
    for threshold in (0.12, 0.20, 0.28):
        p = moments(threshold)
        err, amp = fit_amp(p)
        steps = [0.55, 0.55, 0.45, 0.45, 0.20]
        for _ in range(45):
            changed = False
            for k in range(5):
                for direction in (-1.0, 1.0):
                    q = p[:]
                    q[k] += direction * steps[k]
                    if k < 2:
                        q[k] = max(0.0, min(15.0, q[k]))
                    elif k < 4:
                        q[k] = max(1.2, min(4.8, q[k]))
                    e, aa = fit_amp(q)
                    if e < err:
                        p, err, amp = q, e, aa
                        changed = True
            if not changed:
                steps = [s * 0.62 for s in steps]
                if max(steps) < 0.004:
                    break
        if err < best_err:
            best_err = err
            best_p = p + [amp]
    return best_p

def decode(z):
    return _render(z[0], z[1], z[2], z[3], z[4], z[5])
