            else:
                grad = math.sqrt((u / (a * a)) ** 2 + (v / (b * b)) ** 2)
                sd = (1.0 - rho) * rho / grad
            t = max(0.0, min(1.0, sd + 0.5))
            out.append(amp * t)
    return out

def encode(img):
    def initial(threshold):
        sw = sx = sy = 0.0
        weights = []
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[i * 16 + j] - threshold)
                weights.append(w)
                sw += w
                sx += w * j
                sy += w * i
        if sw < 1e-9:
            return [7.5, 7.5, 3.0, 2.5, 0.0]
        cx, cy = sx / sw, sy / sw
        xx = xy = yy = 0.0
        for i in range(16):
            for j in range(16):
                w = weights[i * 16 + j]
                dx, dy = j - cx, i - cy
                xx += w * dx * dx
                xy += w * dx * dy
                yy += w * dy * dy
        xx, xy, yy = xx / sw, xy / sw, yy / sw
        disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
        l1 = max(0.4, (xx + yy + disc) * 0.5)
        l2 = max(0.4, (xx + yy - disc) * 0.5)
        a, b = 2.0 * math.sqrt(l1), 2.0 * math.sqrt(l2)
        th = 0.5 * math.atan2(2.0 * xy, xx - yy)
        if b > a:
            a, b = b, a
            th += math.pi * 0.5
        return [cx, cy, min(5.0, max(1.2, a)),
                min(5.0, max(1.2, b)), th]

    def fit(start):
        def evaluate(p):
            base = _render(p[0], p[1], p[2], p[3], p[4], 1.0)
            dot = sum(x * y for x, y in zip(img, base))
            den = sum(x * x for x in base) + 1e-12
            amp = max(0.0, min(1.2, dot / den))
            err = sum((y - amp * x) ** 2 for x, y in zip(base, img))
            return err, amp

        p = start[:]
        err, amp = evaluate(p)
        steps = [0.45, 0.45, 0.4, 0.4, 0.18]
        while max(steps) > 0.003:
            changed = False
            for k in range(5):
                for sign in (-1.0, 1.0):
                    q = p[:]
                    q[k] += sign * steps[k]
                    if k < 2:
                        q[k] = max(0.0, min(15.0, q[k]))
