                    e, aa = evaluate(q)
                    if e < err:
                        p, err, amp = q, e, aa
                        changed = True
            if not changed:
                steps = [s * 0.55 for s in steps]
        return err, p + [amp]

    best = None
    for threshold in (0.12, 0.20, 0.28):
        err, z = fit(initial(threshold))
        if best is None or err < best[0]:
            best = (err, z)
