import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            q = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if q < 1e-10:
                d = min(a, b)
            else:
                # First-order signed Euclidean distance to the ellipse.
                g = math.sqrt((u / (a * a)) ** 2 + (v / (b * b)) ** 2)
                d = (1.0 - q) / g
            out.append(amp * max(0.0, min(1.0, 0.5 + d)))
    return out

def encode(img):
    def wrap(t):
        return (t + math.pi / 2.0) % math.pi - math.pi / 2.0

    def start(threshold):
        sw = sx = sy = 0.0
        ws = []
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[i * 16 + j] - threshold)
                ws.append(w)
                sw += w
                sx += w * j
                sy += w * i
        if sw < 1e-10:
            return [7.5, 7.5, 3.0, 2.0, 0.0]
        cx, cy = sx / sw, sy / sw
        xx = xy = yy = 0.0
        for i in range(16):
            for j in range(16):
                w = ws[i * 16 + j]
                dx, dy = j - cx, i - cy
                xx += w * dx * dx
                xy += w * dx * dy
                yy += w * dy * dy
        xx, xy, yy = xx / sw, xy / sw, yy / sw
        disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
        l1 = max(0.25, (xx + yy + disc) / 2.0)
        l2 = max(0.25, (xx + yy - disc) / 2.0)
        a, b = 2.0 * math.sqrt(l1), 2.0 * math.sqrt(l2)
        th = 0.5 * math.atan2(2.0 * xy, xx - yy)
        if b > a:
            a, b, th = b, a, th + math.pi / 2.0
        return [cx, cy, min(5.0, max(1.1, a)),
                min(5.0, max(1.1, b)), wrap(th)]

    def objective(p):
        raw = _render(p[0], p[1], p[2], p[3], p[4], 1.0)
        den = sum(x * x for x in raw) + 1e-12
        amp = max(0.0, min(1.2, sum(x * y for x, y in zip(raw, img)) / den))
        err = sum((y - amp * x) ** 2 for x, y in zip(raw, img))
        return err, amp

    best_err = float("inf")
    best = None
    for threshold in (0.08, 0.18, 0.28, 0.38):
        base = start(threshold)
        for scale in (0.78, 0.94, 1.10, 1.25):
            p = base[:]
            p[2] = min(5.0, max(1.1, p[2] * scale))
            p[3] = min(5.0, max(1.1, p[3] * scale))
            err, amp = objective(p)
            steps = [0.32, 0.32, 0.28, 0.28, 0.14]
            while max(steps) > 0.0007:
                changed = False
                for k in range(5):
                    for sign in (-1.0, 1.0):
                        q = p[:]
                        q[k] += sign * steps[k]
                        if k < 2:
                            q[k] = max(0.0, min(15.0, q[k]))
                        elif k < 4:
                            q[k] = max(1.1, min(5.0, q[k]))
                        else:
                            q[k] = wrap(q[k])
                        e, aa = objective(q)
                        if e < err:
                            p, err, amp = q, e, aa
                            changed = True
                if not changed:
                    steps = [s * 0.58 for s in steps]
            if err < best_err:
                best_err = err
                best = p[:] + [amp]
    return best

def decode(z):
    return _render(z[0], z[1], z[2], z[3], z[4], z[5])
